// The store file holds bearer tokens: a group- or world-readable file is
// refused on read (like SSH refuses loose key permissions) so a
// misconfigured CI image or manual copy can't silently expose credentials.
// Files written by this store are always 0600.
func TestFileStore_RefusesGroupOrWorldReadableFile(t *testing.T) {
	if runtime.GOOS == goosWindows {
		t.Skip("unix permission semantics")
	}
	for name, perm := range map[string]os.FileMode{
		"group-readable": 0o640,
		"world-readable": 0o604,
	} {
		t.Run(name, func(t *testing.T) {
			s := newTestStore(t)
			if err := os.WriteFile(s.path, []byte(`{"svc":{"alice":"tokval"}}`), perm); err != nil {
				t.Fatal(err)
			}
			_, err := s.Get("svc", "alice")
			if err == nil {
				t.Fatalf("Get should refuse a %s token store file", name)
			}
			if !strings.Contains(err.Error(), "0600") || !strings.Contains(err.Error(), s.path) {
				t.Fatalf("error should name the file and the required 0600 permissions, got: %v", err)
			}
		})
	}
}

// A correctly-permissioned file keeps working.
func TestFileStore_Reads0600File(t *testing.T) {
	s := newTestStore(t)
	if err := os.WriteFile(s.path, []byte(`{"svc":{"alice":"tokval"}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	got, err := s.Get("svc", "alice")
	if err != nil {
		t.Fatalf("Get on a 0600 file should succeed, got: %v", err)
	}
	if got != "tokval" {
		t.Fatalf("Get = %q, want %q", got, "tokval")
	}
}

